 "content": "def transform(grid):
    """Replace each solid monochrome rectangle at least 5x5 with color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Every qualifying rectangle contains a 5x5 seed. Extend each uniform
    # rectangle in all directions and mark its cells.
    marked = [[False] * w for _ in range(h)]
    for r0 in range(h - 4):
        for c0 in range(w - 4):
            color = grid[r0][c0]
            if any(grid[r][c] != color
                   for r in range(r0, r0 + 5)
                   for c in range(c0, c0 + 5)):
                continue
            # Grow the 5x5 seed into its maximal uniform rectangle.
            top, bottom, left, right = r0, r0 + 4, c0, c0 + 4
            changed = True
            while changed:
                changed = False
                if top > 0 and all(grid[top - 1][c] == color for c in range(left, right + 1)):
                    top -= 1; changed = True
                if bottom + 1 < h and all(grid[bottom + 1][c] == color for c in range(left, right + 1)):
                    bottom += 1; changed = True
                if left > 0 and all(grid[r][left - 1] == color for r in range(top, bottom + 1)):
                    left -= 1; changed = True
                if right + 1 < w and all(grid[r][right + 1] == color for r in range(top, bottom + 1)):
                    right += 1; changed = True
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    marked[r][c] = True
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out

