                    out[r][c] = 4; r -= 1
                r = r0+5
                while r < h and grid[r][c] == color:
                    out[r][c] = 4; r += 1
            # Fill contiguous rows/columns whose complete span is the block.
            for r in range(r0, r0+5):
                for c in range(max(0,c0-10), min(w,c0+15)):
                    if grid[r][c] == color and all(grid[r][x] == color for x in range(c0,c0+5)):
