            changed = True
            while changed:
                changed = False
                if top > 0 and all(grid[top-1][c] == color for c in range(left,right+1)):
                    top -= 1; changed = True
                if bottom+1 < h and all(grid[bottom+1][c] == color for c in range(left,right+1)):
                    bottom += 1; changed = True
                if left > 0 and all(grid[r][left-1] == color for r in range(top,bottom+1)):
                    left -= 1; changed = True
                if right+1 < w and all(grid[r][right+1] == color for r in range(top,bottom+1)):
                    right += 1; changed = True
            if bottom-top+1 >= 5 and right-left+1 >= 5:
                for r in range(top,bottom+1):
                    for c in range(left,right+1):
                        out[r][c] = 4
    # Some rectangles have a few noisy cells along one boundary. Search 6x7
