    # patches with at least 42. This retains the intended rectangle dimensions.
    for r0 in range(h-5):
        for c0 in range(w-6):
            for color in range(10):
                if sum(grid[r][c] == color for r in range(r0,r0+6) for c in range(c0,c0+7)) >= 35:
                    for r in range(r0,r0+6):
                        for c in range(c0,c0+7): out[r][c] = 4
    for r0 in range(h-6):
        for c0 in range(w-6):
            for color in range(10):
                if sum(grid[r][c] == color for r in range(r0,r0+7) for c in range(c0,c0+7)) >= 42:
                    for r in range(r0,r0+7):
                        for c in range(c0,c0+7): out[r][c] = 4
    return out

