 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find each monochrome panel by its strongest 5x5 seed, then infer the
    # panel's rectangular footprint. These noisy grids contain a few corrupted
    # border cells; the best rectangle is the contiguous window with maximal
    # support for the seed color.
    for r0 in range(h-4):
        for c0 in range(w-4):
            color = grid[r0][c0]
            if sum(grid[r][c] == color for r in range(r0,r0+5) for c in range(c0,c0+5)) != 25:
                continue
            # Candidate panels up to 12x12 around this seed; choose the largest
            # nearly uniform rectangle containing it, requiring >=90% purity.
            best = None
            for top in range(max(0,r0-7), r0+1):
                for bottom in range(r0+4, min(h,r0+12)+1):
                    for left in range(max(0,c0-7), c0+1):
                        for right in range(c0+4, min(w,c0+12)+1):
                            area=(bottom-top)*(right-left)
                            if area < 25: continue
                            same=sum(grid[r][c] == color for r in range(top,bottom) for c in range(left,right))
                            if same/area >= 0.88:
                                score=area
                                if best is None or score>best[0]: best=(score,top,bottom,left,right)
            if best:
                _,top,bottom,left,right=best
                for r in range(top,bottom):
                    for c in range(left,right): out[r][c]=4
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
