 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Infer large same-color patches from row/column spans. In each row, a run
    # of >=5 identical cells is a candidate; group aligned runs across rows.
    runs=[]
    for r in range(h):
        c=0
        while c<w:
            e=c+1
            while e<w and grid[r][e]==grid[r][c]: e+=1
            if e-c>=5: runs.append((r,c,e,grid[r][c]))
            c=e
    # solid patches are vertical overlaps of long runs of the same color
    for r0,c0,c1,col in runs:
        end=r0+1
        while end<h and all(grid[end][c]==col for c in range(c0,c1)): end+=1
        if end-r0>=5:
            for r in range(r0,end):
                for c in range(c0,c1): out[r][c]=4
    # Extend to nearly solid rectangle edges: 7x7 in demo examples, with up
    # to 7 noisy cells while the core supplies strong color evidence.
    for hh,ww,threshold in [(6,7,35),(7,7,42)]:
        for r0 in range(h-hh+1):
            for c0 in range(w-ww+1):
                for col in range(10):
                    if sum(grid[r][c]==col for r in range(r0,r0+hh) for c in range(c0,c0+ww))>=threshold:
                        for r in range(r0,r0+hh):
                            for c in range(c0,c0+ww): out[r][c]=4
    return out

