    # Their boundaries may have a few noisy cells, so rank each contiguous
    # rectangular window by the number of matching cells of its central color.
    for hh in range(5, min(10,h)+1):
        for ww in range(5, min(12,w)+1):
            for r0 in range(h-hh+1):
                for c0 in range(w-ww+1):
                    # Consider colors represented by at least 70% of rectangle.
                    counts={}
