                        for c in range(c0,c0+ww):
                            col=grid[r][c]; counts[col]=counts.get(col,0)+1
                    color,n=max(counts.items(), key=lambda p:p[1])
                    if n >= hh*ww*0.82 and n >= 30:
                        # Require reasonably complete rows and columns; this
                        # avoids painting unrelated scattered frequent colors.
                        if min(sum(grid[r][c]==color for c in range(c0,c0+ww)) for r in range(r0,r0+hh)) >= ww-2 and min(sum(grid[r][c]==color for r in range(r0,r0+hh)) for c in range(c0,c0+ww)) >= hh-2:
