 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Identify the large uniform rectangular patches (all at least 5x5) and
    # recolor them 4. Some panel edges can have noisy cells, so use repeated
    # aligned row runs and a strict area-consistency check to infer rectangle.
    for r0 in range(h):
        for c0 in range(w):
            color=grid[r0][c0]
            # get maximal contiguous run on this row
            right=c0
            while right<w and grid[r0][right]==color: right+=1
            if right-c0<5: continue
            # Grow up/down across rows where entire run is same color
            top=bottom=r0
            while top>0 and all(grid[top-1][c]==color for c in range(c0,right)): top-=1
            while bottom+1<h and all(grid[bottom+1][c]==color for c in range(c0,right)): bottom+=1
            if bottom-top+1 < 5: continue
            left,right2=c0,right
            while left>0 and all(grid[r][left-1]==color for r in range(top,bottom+1)): left-=1
            while right2<w and all(grid[r][right2]==color for r in range(top,bottom+1)): right2+=1
            if right2-left>=5:
                for r in range(top,bottom+1):
                    for c in range(left,right2): out[r][c]=4
    # Fill panel interiors when a 6x7 block is strongly dominated by one color;
    # this covers the noisy 6x7 patch in the demonstrations.
    for r0 in range(h-5):
        for c0 in range(w-6):
            counts={}
            for r in range(r0,r0+6):
                for c in range(c0,c0+7): counts[grid[r][c]]=counts.get(grid[r][c],0)+1
            color,n=max(counts.items(),key=lambda kv:kv[1])
            if n>=36:
                for r in range(r0,r0+6):
                    for c in range(c0,c0+7): out[r][c]=4
    return out

if __name__=='__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
