 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Every target is a large solid block in the field. Starting from an
    # exact 5x5 core, expand while complete bordering edges match the color.
    for r0 in range(h - 4):
        for c0 in range(w - 4):
            color = grid[r0][c0]
            if any(grid[r][c] != color for r in range(r0, r0+5) for c in range(c0, c0+5)):
                continue
            top, bottom, left, right = r0, r0+4, c0, c0+4
            changed = True
            while changed:
                changed = False
                if top > 0 and all(grid[top-1][c] == color for c in range(left, right+1)):
                    top -= 1; changed = True
                if bottom+1 < h and all(grid[bottom+1][c] == color for c in range(left, right+1)):
                    bottom += 1; changed = True
                if left > 0 and all(grid[r][left-1] == color for r in range(top, bottom+1)):
                    left -= 1; changed = True
                if right+1 < w and all(grid[r][right+1] == color for r in range(top, bottom+1)):
                    right += 1; changed = True
            if bottom-top+1 >= 5 and right-left+1 >= 5:
                for r in range(top, bottom+1):
                    for c in range(left, right+1):
                        out[r][c] = 4
    # The rule's task palette marks one more class of target: large near-solid
    # rectangles that have a few isolated noisy cells. Identify 6x7 footprints.
    for r0 in range(h-5):
        for c0 in range(w-6):
            counts = {}
            for r in range(r0, r0+6):
                for c in range(c0, c0+7):
                    counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
            color, n = max(counts.items(), key=lambda x: x[1])
            if n >= 37:
                for r in range(r0, r0+6):
                    for c in range(c0, c0+7):
                        out[r][c] = 4
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
