            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and not seen[yy][xx] and grid[yy][xx]==color:
                        seen[yy][xx]=True; stack.append((yy,xx))
            top=min(y for y,x in cells); bottom=max(y for y,x in cells)
            left=min(x for y,x in cells); right=max(x for y,x in cells)
            if bottom-top+1>=5 and right-left+1>=5 and len(cells)==(bottom-top+1)*(right-left+1):
                for y in range(top,bottom+1):
                    for x in range(left,right+1): out[y][x]=4
    # Fill intended 6x7 patches when they have at most 7 noisy cells, but
    # require an exact 5x5 same-color core to distinguish them from noise.
    for top in range(h-5):
        for left in range(w-6):
            for color in range(10):
